    [6060]={name="Flax Bracers",quality=1,ilvl=5,reqLevel=2,sourceType="quest_reward",instructions="Reward from the quest 'The Damned'. Pick it over the other reward choices. Starts with Novice Elreth in Tirisfal Glades. Objective: Novice Elreth requires 6 Scavenger Paws and 6 Duskbat Wings.",zone="Tirisfal Glades",questName="The Damned",lore="My duties include tending to our wounded warriors, tailoring armor and clothes, and assisting Shadow Priest Sarvis with whatever else he might need."},
    [6062]={name="Heavy Cord Bracers",quality=1,ilvl=10,reqLevel=5,sourceType="quest_reward",instructions="Reward from the quest 'Thwarting Kolkar Aggression'. Pick it over the other reward choices. Starts with Lar Prowltusk in Durotar. Objective: Lar Prowltusk outside of Sen'jin Village wants you to destroy the 3 sets of Attack Plans held within Kolkar Crag.",zone="Durotar",questName="Thwarting Kolkar Aggression",lore="Lower your voice. The Kolkar centaurs lie just over the ridge to the west in Kolkar Crag."},
    [6076]={name="Tapered Pants",quality=1,ilvl=5,reqLevel=2,sourceType="quest_reward",instructions="Reward from the quest 'Bounty on Garrick Padfoot'. Pick it over the other reward choices. Starts with Deputy Willem in Elwynn Forest. Objective: Kill Garrick Padfoot and bring his head to Deputy Willem at Northshire Abbey.",zone="Elwynn Forest",questName="Bounty on Garrick Padfoot",lore="Garrick Padfoot - a cutthroat who's plagued our farmers and merchants for weeks - was seen at a shack near the vineyards, which lies east of the Abbey and across the bridge."},
    [6098]={name="Neophyte's Robe",quality=0,ilvl=1,reqLevel=1,sourceType="vendor",instructions="Bought from Thomas Yance.",zone="Old Hillsbrad Foothills",npc="Thomas Yance"},
    [6148]={name="Web-covered Boots",quality=1,ilvl=10,reqLevel=5,sourceType="rare_npc",instructions="Drops from Mother Fang.",zone="Elwynn Forest",npc="Mother Fang"},
    [6173]={name="Snow Boots",quality=1,ilvl=5,reqLevel=1,sourceType="quest_reward",instructions="Reward from the quest 'A New Threat'. Pick it over the other reward choices. Starts with Balir Frosthammer in Dun Morogh. Objective: Balir Frosthammer wants you to kill 6 Rockjaw Troggs and 6 Burly Rockjaw Troggs.",zone="Dun Morogh",questName="A New Threat",lore="I hope you're here to lend us a hand. After the last trogg attack, we could use all the help we can get. I hear the buggers have been popping up all across the lands, and it seems Coldridge Valley is no exception."},
    [6185]={name="Bear Shawl",quality=1,ilvl=5,reqLevel=1,sourceType="quest_reward",instructions="Reward from the quest 'A New Threat'. Pick it over the other reward choices. Starts with Balir Frosthammer in Dun Morogh. Objective: Balir Frosthammer wants you to kill 6 Rockjaw Troggs and 6 Burly Rockjaw Troggs.",zone="Dun Morogh",questName="A New Threat",lore="I hope you're here to lend us a hand. After the last trogg attack, we could use all the help we can get. I hear the buggers have been popping up all across the lands, and it seems Coldridge Valley is no exception."},
