    [6215]={name="Balanced Fighting Stick",quality=2,ilvl=13,reqLevel=5,sourceType="quest_reward",instructions="Reward from the quest 'Wanted: \"Hogger\"'. Pick it over the other reward choices.",zone="Elwynn Forest",questName="Wanted:  \"Hogger\"",lore="Wanted: Hogger A huge gnoll, Hogger, is prowling the woods in southwestern Elwynn. He has overpowered all attempts at his capture. The Stormwind Army has placed a generous bounty on the Gnoll."},
