    [9598]={name="Sleeping Robes",quality=2,ilvl=10,reqLevel=3,sourceType="quest_reward",instructions="Reward from the quest 'Druid of the Claw'. Pick it over the other reward choices. Starts with Oben Rageclaw in Teldrassil. Objective: Oben Rageclaw wants you to kill his soulless body, and then use the Voodoo Charm.",zone="Teldrassil",questName="Druid of the Claw",lore="After examining this charm, I see now what must be done. Please take it, and do as I ask. You are to explore the deepest areas of the Ban'ethil Barrow Den."},
    [9600]={name="Lace Pants",quality=1,ilvl=12,reqLevel=5,sourceType="quest_reward",instructions="Reward from the quest 'Sathrah's Sacrifice'. Pick it over the other reward choices. Starts with Priestess A'moora in Darnassus. Objective: Priestess A'moora wants you to place Lady Sathrah's silvery spinnerets at the fountain inside the temple, and then return to her.",zone="Darnassus",questName="Sathrah's Sacrifice",lore="Now you must finish the task to which you have been appointed. Take the spinnerets and offer Lady Sathrah's sacrifice to Elune; lay the great spider to rest."},
    [9603]={name="Gritroot Staff",quality=2,ilvl=10,reqLevel=4,sourceType="quest_reward",instructions="Reward from the quest 'The Relics of Wakening'. Pick it over the other reward choices. Starts with Athridas Bearmantle in Teldrassil. Objective: Retrieve the Relics of Wakening and bring them to Athridas Bearmantle in Dolanaar.",zone="Teldrassil",questName="The Relics of Wakening",lore="Gnarlpine invaders were seen ravaging the Ban'ethil Barrow Den to the west. The slumbering druids will be trapped in the Emerald Dream for eternity, unaware of their fate, unless we help."},
