    [10549]={name="Rancher's Trousers",quality=2,ilvl=12,reqLevel=6,sourceType="quest_reward",instructions="Reward from the quest 'Protecting the Herd'. Pick it over the other reward choices. Starts with Rudra Amberstill in Dun Morogh. Objective: Rudra Amberstill wants you to slay Vagash and bring his fang to her at the Ram ranch.",zone="Dun Morogh",questName="Protecting the Herd",lore="We heard the cries in the middle of the night. Then this morning, sure enough, the herd was missing two rams. That dastardly beast known as Vagash has been preying on our livelihood."},
    [10550]={name="Wooly Mittens",quality=1,ilvl=12,reqLevel=7,sourceType="quest_reward",instructions="Reward from the quest 'Tundra MacGrann's Stolen Stash'. Pick it over the other reward choices. The quest is in Dun Morogh. Objective: Retrieve Tundra MacGrann's dried meats from the stolen meat locker in Old Icebeard's cave.",zone="Dun Morogh",questName="Tundra MacGrann's Stolen Stash",lore="I had a month's worth of dried meats salted and locked away for the cold season. Kept it locked so the bears wouldn't get it! But while I was off hunting deer, that beast, Old Icebeard, made off with the meat locker."},
    [10553]={name="Foreman Vest",quality=2,ilvl=13,reqLevel=8,sourceType="rare_npc",instructions="Drops from Gibblewilt.",zone="Dun Morogh",npc="Gibblewilt"},
    [10554]={name="Foreman Pants",quality=2,ilvl=13,reqLevel=8,sourceType="rare_npc",instructions="Drops from Gibblewilt.",zone="Dun Morogh",npc="Gibblewilt"},
    [10655]={name="Sedgeweed Britches",quality=1,ilvl=5,reqLevel=2,sourceType="quest_reward",instructions="Reward from the quest 'Iverron's Antidote'. Pick it over the other reward choices. Starts with Dirania Silvershine in Teldrassil. Objective: Collect 7 Hyacinth Mushrooms, 4 Moonpetal Lilies, and 1 Webwood Ichor for Dirania Silveshine in Shadowglen.",zone="Teldrassil",questName="Iverron's Antidote",lore="The antidote is ready. Please see that Iverron drinks it. There is something that you should know -- the antidote -- it will only remain viable for 5 minutes."},
    [11187]={name="Stemleaf Bracers",quality=1,ilvl=5,sourceType="quest_reward",instructions="Reward from the quest 'The Balance of Nature'. Pick it over the other reward choices. Starts with Conservator Ilthalaine in Teldrassil. Objective: Kill 7 Young Nightsabers and 4 Young Thistle Boars and return to Conservator Ilthalaine.",zone="Teldrassil",questName="The Balance of Nature",lore="Greetings. I am Conservator Ilthalaine. My purpose in Shadowglen is to ensure that the balance of nature is maintained."},
    [11189]={name="Woodland Robes",quality=1,ilvl=5,sourceType="quest_reward",instructions="Reward from the quest 'Webwood Egg'. Pick it over the other reward choices. Starts with Gilshalan Windwalker in Teldrassil. Objective: Bring a Webwood Egg to Gilshalan in Aldrassil.",zone="Teldrassil",questName="Webwood Egg",lore="Now that I have the spiders' venom, I'd like some live specimens to study. Unfortunately, capturing a living, giant spider is more than I can ask of you, young."},
    [11190]={name="Viny Gloves",quality=1,ilvl=5,sourceType="quest_reward",instructions="Reward from the quest 'The Woodland Protector'. Pick it over the other reward choices. Starts with Tarindrella in Teldrassil. Objective: Collect 8 Fel Moss and bring them to Tarindrella.",zone="Teldrassil",questName="The Woodland Protector",lore="Something evil is brewing in the forests of Teldrassil. Look long the hills to where the peaceful furbolgs used to dwell. They have deserted their homes and are amassing under the name of the Gnarlpine tribe."},
    [11191]={name="Farmer's Boots",quality=1,ilvl=10,reqLevel=6,sourceType="quest_reward",instructions="Reward from the quest 'Princess Must Die!'. Pick it over the other reward choices.",zone="Elwynn Forest",questName="Princess Must Die!",lore="The Brackwells have a prize-winning pig, Princess. The sow is HUGE, and she got that way from sneaking over here and eating my veggies! So before she comes to our fields...Princess must die!"},
    [11192]={name="Outfitter Gloves",quality=1,ilvl=5,sourceType="quest_reward",instructions="Reward from the quest 'Skirmish at Echo Ridge'. Pick it over the other reward choices. Starts with Marshal McBride in Elwynn Forest. Objective: Kill 12 Kobold Laborers, then return to Marshal McBride at Northshire Abbey.",zone="Elwynn Forest",questName="Skirmish at Echo Ridge",lore="Your previous investigations are proof that the Echo Ridge Mine needs purging. Return to the mine and help clear it of kobolds. Waste no time."},
    [11287]={name="Lesser Magic Wand",quality=2,ilvl=15,reqLevel=5,sourceType="profession",instructions="Crafted with Enchanting (requires skill 1).",profession="Enchanting"},
    [11475]={name="Wine-stained Cloak",quality=1,ilvl=5,reqLevel=2,sourceType="quest_reward",instructions="Reward from the quest 'Grape Manifest'. Pick it over the other reward choices. Starts with Milly Osworth in Elwynn Forest. Objective: Bring the Grape Manifest to Brother Neals in Northshire Abbey.",zone="Elwynn Forest",questName="Grape Manifest",lore="You'll find Brother Neals in the abbey, in the bell tower... where he likes to taste his wine."},
    [11847]={name="Battered Cloak",quality=1,ilvl=5,sourceType="quest_reward",instructions="Reward from the quest 'The Mindless Ones'. Pick it over the other reward choices. Starts with Shadow Priest Sarvis in Tirisfal Glades. Objective: Shadow Priest Sarvis wants you to kill 8 Mindless Zombies and 8 Wretched Zombies.",zone="Tirisfal Glades",questName="The Mindless Ones",lore="We Forsaken are at war with the Lich King's army of the Scourge: necromantically raised armies of the undead, foul beasts of the north, and tormented spectres."},
    [11848]={name="Flax Belt",quality=1,ilvl=5,reqLevel=2,sourceType="quest_reward",instructions="Reward from the quest 'Scavenging Deathknell'. Pick it over the other reward choices. Starts with Deathguard Saltain in Tirisfal Glades. Objective: Search Deathknell and the vicinity for 6 pieces of Scavenged Goods, and return them to Deathguard Saltain.",zone="Tirisfal Glades",questName="Scavenging Deathknell",lore="You there! If you're looking for something to make yourself useful, then listen up! We need fresh out-of-the-ground recruits to head into Deathknell and search for any sort of useful equipment."},
    [11850]={name="Short Duskbat Cape",quality=1,ilvl=5,reqLevel=2,sourceType="quest_reward",instructions="Reward from the quest 'Scavenging Deathknell'. Pick it over the other reward choices. Starts with Deathguard Saltain in Tirisfal Glades. Objective: Search Deathknell and the vicinity for 6 pieces of Scavenged Goods, and return them to Deathguard Saltain.",zone="Tirisfal Glades",questName="Scavenging Deathknell",lore="You there! If you're looking for something to make yourself useful, then listen up! We need fresh out-of-the-ground recruits to head into Deathknell and search for any sort of useful equipment."},
    [12296]={name="Spark of the People's Militia",quality=2,ilvl=17,reqLevel=9,sourceType="quest_reward",instructions="Reward from the quest 'The People's Militia'. Pick it over the other reward choices.",zone="Westfall",questName="The People's Militia",lore="We believe they are hiding out in the Dagger Hills, plotting their next move. Slay the wretches in the name of The People's Militia."},
    [12299]={name="Netted Gloves",quality=1,ilvl=8,reqLevel=5,sourceType="quest_reward",instructions="Reward from the quest 'Proof of Demise'. Pick it over the other reward choices. Starts with Deathguard Burgess in Tirisfal Glades. Objective: Bring 10 Scarlet Insignia Rings to Deathguard Burgess in Brill.",zone="Tirisfal Glades",questName="Proof of Demise",lore="Executor Zygand tells me you've been out killing Scarlet Crusaders. Tirisfal Glades is crawling with them."},
