    [15443]={name="Kris of Orgrimmar",quality=2,ilvl=18,reqLevel=9,sourceType="quest_reward",instructions="Reward from the quest 'Hidden Enemies'. Pick it over the other reward choices. Starts with Thrall in Ragefire Chasm. Objective: Kill Bazzalan and Jergosh the Invoker before returning to Thrall in Orgrimmar.",zone="Orgrimmar",questName="Hidden Enemies",lore="You are one of my lieutenants! Prepare yourself. I will call upon you soon. My time spent on the Searing Blade may be all but wasted now, but that does not mean that the Shadow Council's schemes elsewhere must suffer."},
    [15444]={name="Staff of Orgrimmar",quality=2,ilvl=18,reqLevel=9,sourceType="quest_reward",instructions="Reward from the quest 'Hidden Enemies'. Pick it over the other reward choices. Starts with Thrall in Ragefire Chasm. Objective: Kill Bazzalan and Jergosh the Invoker before returning to Thrall in Orgrimmar.",zone="Orgrimmar",questName="Hidden Enemies",lore="You are one of my lieutenants! Prepare yourself. I will call upon you soon. My time spent on the Searing Blade may be all but wasted now, but that does not mean that the Shadow Council's schemes elsewhere must suffer."},
    [15449]={name="Ghastly Trousers",quality=3,ilvl=18,reqLevel=9,sourceType="quest_reward",instructions="Reward from the quest 'The Power to Destroy...'. Pick it over the other reward choices. Starts with Varimathras in Undercity. Objective: Bring the books Spells of Shadow and Incantations from the Nether to Varimathras in Undercity.",zone="Ragefire Chasm",questName="The Power to Destroy...",lore="Many denizens of the Legion bestow gifts on their followers as you may well know. Some of these gifts the Dark Lady feels would be better off in her hands than in the hands of those with..."},
    [15452]={name="Featherbead Bracers",quality=2,ilvl=18,reqLevel=9,sourceType="quest_reward",instructions="Reward from the quest 'Returning the Lost Satchel'. Pick it over the other reward choices. Starts with Maur Grimtotem in Thunder Bluff. Objective: Take the Grimtotem Satchel to Rahauro in Thunder Bluff.",zone="Ragefire Chasm",questName="Returning the Lost Satchel",lore="You find a satchel under the body of the tauren. It is still gripped tightly in his arms as though he was trying to protect it while being attacked by the troggs."},
